query ListMetaobjectsByType($type: String!, $cursor: String) {
            metaobjects(type: $type, first: 50, after: $cursor) {
              pageInfo { hasNextPage endCursor }
              edges { node { id fields { key value } } }
            }
          }

query FetchMetaobjectReferences($id: ID!) {
      metaobject(id: $id) {
        referencedBy(first: 50) {
          edges {
            node {
              key
              namespace
              referencer {
                __typename
                ... on Product { id title }
                ... on Collection { id title }
                ... on Article { id title }
                ... on Metaobject { id type }
              }
            }
          }
          pageInfo { hasNextPage }
        }
      }
    }

